/** 将服务端仍缓存的仓库预设显示为中文，返回新对象，不写回原数据。 */
export function localizeTemplate<T>(value: T): T {
  if (typeof value === "string") return (TEMPLATE_TEXT[value] ?? value) as T;
  if (Array.isArray(value)) return value.map(item => localizeTemplate(item)) as T;
  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localizeTemplate(item)])) as T;
  return value;
}

/** 将已知部门标识转换为显示名称，未知的自定义部门保持原样。 */
export function departmentLabel(id: string): string {
  const names: Record<string, string> = { science: '科研部', administration: '行政部', engineering: '工程部', medical: '医疗部', agriculture: '农业部', psychology: '心理部', governance: '治理部', operations: '运营部', finance: '财务部', sales: '销售部', people: '人力资源部', mining: '采矿部', 'life-support': '生命保障部', 'alignment-research': '对齐研究部', 'capability-research': '能力研究部', 'deployment-engineering': '部署工程部', communications: '传播部' };
  return names[id] ?? TEMPLATE_TEXT[id] ?? id;
}

/** 已知状态与情绪枚举的中文名称；不改变存档或计算使用的值。 */
export function displayLabel(value: string | undefined | null): string {
  if (!value) return '—';
  const names: Record<string, string> = { defiant: '抗拒', technological: '技术', resource: '资源', psychological: '心理', positive: '积极', negative: '消极', resigned: '无奈', environmental: '环境', infrastructure: '基础设施', social: '社会', political: '政治', economic: '经济', scientific: '科研', medical: '医疗', low: '低落', tense: '紧张', steady: '平稳', rising: '高涨', focused: '专注', anxious: '焦虑', despair: '绝望', hopeful: '充满希望', neutral: '平静', optimistic: '乐观', confident: '自信', happy: '愉快', sad: '悲伤', angry: '愤怒', calm: '平静', stressed: '压力较大', content: '满足', fearful: '恐惧', determined: '坚定', exhausted: '疲惫', turn_loop: '逐回合', 'turn-loop': '逐回合', 'batch-trajectory': '批量轨迹', 'batch-point': '单点预测', complete: '已完成', running: '运行中', error: '错误', aborted: '已中止', pending: '等待中', junior: '初级', senior: '高级', lead: '负责人', chief: '主管' };
  return names[value] ?? departmentLabel(value);
}

/** 翻译程序生成的岗位格式，保留未知的自定义岗位。 */
export function roleLabel(role: string): string {
  const known = localizeTemplate(role);
  if (known !== role) return known;
  if (role === 'Child') return '儿童';
  const match = /^(Junior|Senior|Lead) (.+) Specialist$/.exec(role);
  if (!match) return role;
  const trades: Record<string, string> = {
    'General Medicine': '全科医学', 'Radiation Medicine': '放射医学', Surgery: '外科', Psychiatry: '精神医学', 'Emergency Medicine': '急诊医学',
    Structural: '结构工程', 'Life Support': '生命保障', 'Power Systems': '电力系统', Communications: '通信', Robotics: '机器人',
    Hydroponics: '水培', 'Soil Science': '土壤科学', Botany: '植物学', Nutrition: '营养学', 'Water Systems': '供水系统',
    Geology: '地质学', 'Atmospheric Science': '大气科学', Biology: '生物学', Chemistry: '化学', Astrophysics: '天体物理',
    Operations: '运营', Logistics: '后勤', HR: '人力资源', Planning: '规划', 'Clinical Psychology': '临床心理',
    'Social Psychology': '社会心理', 'Occupational Therapy': '作业治疗', Policy: '政策', Law: '法律', Diplomacy: '外交',
    General: '综合事务', Support: '支持事务',
  };
  const trade = trades[match[2]] ?? departmentLabel(match[2]);
  if (trade === match[2] && !/[\u4e00-\u9fff]/.test(trade)) return role;
  const ranks: Record<string, string> = { Junior: '初级', Senior: '高级', Lead: '首席' };
  return `${ranks[match[1]]}${trade}专家`;
}

/** 系统状态字段的中文显示名称，底层标识不变。 */
export function metricLabel(key: string): string {
  const names: Record<string, string> = {
    population: '人口', powerKw: '电力（kW）', foodMonthsReserve: '食物储备（月）', waterLitersPerDay: '日供水量（升）',
    pressurizedVolumeM3: '加压容积（立方米）', lifeSupportCapacity: '生命保障容量', infrastructureModules: '基础设施模块',
    scienceOutput: '科研产出', morale: '士气',
  };
  return names[key] ?? localizeTemplate(key);
}
